/**
 * Fastify application shell. FROZEN integration file (lead-owned).
 *
 * Lane owners: do NOT edit this file. Export your routes from
 * `src/modules/<your-module>/index.ts` as
 *   `export default async function routes(app: FastifyInstance)`
 * and message the Lead to register it.
 */

import Fastify, { type FastifyInstance } from 'fastify';
import cors from '@fastify/cors';
import cookie from '@fastify/cookie';
import multipart from '@fastify/multipart';
import { migrate, dbHealth, DB_PATH } from './db/index.js';

const startedAt = Date.now();
export const VERSION = '0.1.0';

/** Every module registers here, in lifecycle-stage order. */
const MODULE_ROUTES: Array<{ name: string; path: string }> = [
  { name: 'health', path: './modules/health/index.js' },
  // Lane A — document creation
  { name: 'projects', path: './modules/projects/index.js' },
  { name: 'requirements', path: './modules/requirements/index.js' },
  { name: 'usecases', path: './modules/usecases/index.js' },
  { name: 'scenarios', path: './modules/scenarios/index.js' },
  { name: 'testcases', path: './modules/testcases/index.js' },
  { name: 'matrix', path: './modules/matrix/index.js' },
  { name: 'exports', path: './modules/exports/index.js' },
  // Lane B — QA project management
  { name: 'cycles', path: './modules/cycles/index.js' },
  { name: 'runs', path: './modules/runs/index.js' },
  { name: 'regression', path: './modules/regression/index.js' },
  { name: 'metrics', path: './modules/metrics/index.js' },
  { name: 'defects', path: './modules/defects/index.js' },
  { name: 'environment', path: './modules/environment/index.js' },
  // Lane C — automation engines
  { name: 'apitester', path: './modules/apitester/index.js' },
  { name: 'dbtester', path: './modules/dbtester/index.js' },
  { name: 'webtester', path: './modules/webtester/index.js' },
  { name: 'execute', path: './modules/execute/index.js' },
  // Lane D — AI
  { name: 'ai', path: './modules/ai/index.js' },
  // Lane E — learning
  { name: 'courses', path: './modules/courses/index.js' },
  { name: 'certificates', path: './modules/certificates/index.js' },
  // Lane F/G — automation codegen + multi-worker AI agent pool (v1.2)
  { name: 'codegen', path: './modules/codegen/index.js' },
  { name: 'agents', path: './modules/agents/index.js' },
];

export async function buildApp(opts: { logger?: boolean } = {}): Promise<FastifyInstance> {
  const app = Fastify({
    logger: opts.logger ?? false,
    bodyLimit: 32 * 1024 * 1024,
  });

  await app.register(cors, { origin: true, credentials: true });
  await app.register(cookie);
  await app.register(multipart, { limits: { fileSize: 32 * 1024 * 1024 } });

  migrate();

  // Root banner so a bare GET / is friendly and proves the process is alive.
  app.get('/', async () => ({
    name: 'QATools API',
    version: VERSION,
    docs: '/api/health',
    db: DB_PATH,
    uptime_s: Math.round((Date.now() - startedAt) / 1000),
  }));

  // Optional-module registration: a module that is absent or throws is reported, not fatal.
  const registration: Array<{ name: string; ok: boolean; error?: string }> = [];
  for (const mod of MODULE_ROUTES) {
    try {
      const imported = (await import(mod.path)) as { default?: unknown };
      const plugin = imported.default;
      if (typeof plugin !== 'function') {
        registration.push({ name: mod.name, ok: false, error: 'no default export' });
        continue;
      }
      await app.register(plugin as never, { prefix: '/api' });
      registration.push({ name: mod.name, ok: true });
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      registration.push({ name: mod.name, ok: false, error: message });
      app.log.warn?.(`module ${mod.name} not registered: ${message}`);
    }
  }

  app.get('/api/health', async () => ({
    status: 'ok',
    version: VERSION,
    uptime: Math.round((Date.now() - startedAt) / 1000),
    db: dbHealth(),
    db_path: DB_PATH,
    modules: registration,
  }));

  // Uniform 404 / error envelopes.
  app.setNotFoundHandler((req, reply) => {
    reply.code(404).send({
      error: { code: 'not_found', message: `Route ${req.method} ${req.url} not found` },
    });
  });

  app.setErrorHandler((err: unknown, _req, reply) => {
    const e = err as { statusCode?: number; code?: string; message?: string };
    const status = typeof e.statusCode === 'number' && e.statusCode >= 400 ? e.statusCode : 500;
    reply.code(status).send({
      error: {
        code: e.code ?? 'internal_error',
        message: e.message || 'Internal Server Error',
      },
    });
  });

  return app;
}

/** Entry point when run directly. */
const isMain =
  process.argv[1] &&
  (process.argv[1].endsWith('server.ts') || process.argv[1].endsWith('server.js'));

if (isMain) {
  const port = Number(process.env.PORT ?? 5174);
  const host = process.env.HOST ?? '127.0.0.1';
  const app = await buildApp({ logger: true });
  try {
    await app.listen({ port, host });
    // eslint-disable-next-line no-console
    console.log(`QATools API listening on http://${host}:${port}  (db: ${DB_PATH})`);
  } catch (err) {
    app.log.error(err);
    process.exit(1);
  }
}
